    pub(crate) fn merge_captured_param_lists(
        current: &mut Vec<(std::sync::Arc<str>, crate::util::PercentDecodedStr)>,
        incoming: Vec<(std::sync::Arc<str>, crate::util::PercentDecodedStr)>,
    ) {
        if incoming.is_empty() {
            return;
        }
        current.extend(incoming);
    }

    pub(crate) fn apply_allow_header(
        headers: &mut http::HeaderMap,
        allow_value: &mut Option<bytes::Bytes>,
    ) {
        match allow_value.take() {
            Some(value) if !headers.contains_key(http::header::ALLOW) => {
                headers.insert(
                    http::header::ALLOW,
                    http::HeaderValue::from_maybe_shared(value)
                        .expect("invalid `Allow` header"),
                );
            }
            _ => {}
        }
    }

    pub(crate) fn apply_exact_content_length(
        size_hint: http_body::SizeHint,
        headers: &mut http::HeaderMap,
    ) {
        if headers.contains_key(http::header::CONTENT_LENGTH) {
            return;
        }
        if let Some(size) = size_hint.exact() {
            let header_value = if size == 0 {
                #[allow(clippy::declare_interior_mutable_const)]
                const ZERO: http::HeaderValue = http::HeaderValue::from_static("0");
                ZERO
            } else {
                let mut buffer = itoa::Buffer::new();
                http::HeaderValue::from_str(buffer.format(size)).unwrap()
            };
            headers.insert(http::header::CONTENT_LENGTH, header_value);
        }
    }
}

